const owners:string[]=[],dbs:Ledger[]=[];
const time=Date.parse('2026-09-16T00:00:00.000Z'),sha=(value:string|Buffer)=>createHash('sha256').update(value).digest('hex');
const gitExecutable=realpathSync.native(execFileSync('where.exe',['git.exe'],{encoding:'utf8',windowsHide:true,shell:false}).split(/\r?\n/u)[0]);
const git=(cwd:string,...args:string[])=>execFileSync(gitExecutable,args,{cwd,encoding:'utf8',windowsHide:true,shell:false});
afterEach(()=>{for(const db of dbs.splice(0))if(db.open)db.close();for(const owner of owners.splice(0)){const exact=realpathSync.native(owner),base=join(realpathSync.native(tmpdir()),'cue-git-staging-driver-');if(!isAbsolute(exact)||(!exact.startsWith(base))||relative(exact,owner)!=='')throw Error('fixture_cleanup_target_untrusted');rmSync(exact,{recursive:true,force:true});}});

export function fixture(executionAfterRead:'unchanged'|'restore'|'diverge',configureHost?:(context:{host:any;configuration:any;db:Ledger;publication:string;storage:string;git:(...args:string[])=>string})=>void){
 const owner=realpathSync.native(mkdtempSync(join(tmpdir(),'cue-git-staging-driver-')));owners.push(owner);
 const publication=join(owner,'publication'),storage=join(owner,'storage');mkdirSync(publication);mkdirSync(storage);
 git(publication,'init');git(publication,'config','user.name','Cue fixture');git(publication,'config','user.email','cue-fixture@example.invalid');
 writeFileSync(join(publication,'target.txt'),'base\n');git(publication,'add','target.txt');git(publication,'commit','-m','fixture base');
 const db=openLedger(join(owner,'ledger.db'));dbs.push(db);
 const envelope=normalizeEnvelope({run_id:'workflow',worktree_realpath:publication,allowed_actions:['file_change','read'],egress:[],expires_at:'2026-09-17T00:00:00.000Z',autonomy_level:'bounded'});
 const run={taskId:'root-task',runId:'workflow',envelopeHash:envelopeHash(envelope),envelope,goal:'fixture: publish staged bytes',scope:'fixture'};
 db.prepare("INSERT INTO task VALUES('root-task','awaiting_approval',NULL,'now')").run();db.prepare("INSERT INTO envelope VALUES(?,?,'[]','now')").run(run.envelopeHash,publication);db.prepare("INSERT INTO run VALUES('workflow','root-task',?,0,'now')").run(run.envelopeHash);
 const policy=saveSelectionPolicy(db,{policyId:'policy',expectedRevision:null,createdAt:new Date(time).toISOString(),sourceVersion:'fixture',policy:{version:'cue-selection-v1',mode:'efficiency',qualityMinimum:.5,costBasis:1,timeBasisMs:1,currency:'TEST',costLimit:null,remainingTimeMs:null,maxEstimateAgeMs:100,allowedCandidateIds:['fixture-agent'],pinnedCandidateId:null}});
 const subject=Object.fromEntries(SUBJECT_FIELDS.map(key=>[key,key.endsWith('Sha256')?'a'.repeat(64):`fixture-${key}`])) as MeasurementSubject,evidence=new Map<string,Buffer>(),refs:Record<string,{id:string;sha256:string}>={};
 for(const probe of [...WRITE_PROBES,...MODEL_PROBES]){const bytes=Buffer.from(JSON.stringify({probe,subjectDigest:subjectDigest(subject),measuredAt:new Date(time-1).toISOString(),kind:'live',status:'pass'}));evidence.set(probe,bytes);refs[probe]={id:probe,sha256:sha(bytes)};}
 expect(createCapabilityAdmission({now:()=>time,maxAgeMs:100,resolveEvidence:(ref:any)=>evidence.get(ref.id)})(subject,refs)).toMatchObject({implementationEligible:true,reasons:[]});
 const catalog=createIntegrationCatalog({now:()=>time,maxAgeMs:100,currentSubjectDigest:()=>subjectDigest(subject)},[{canonicalId:'fixture-agent',toolId:'fixture-tool',kind:'agent',aliases:[],installation:'installed',protocol:'verified',authReference:'fixture-account',authAvailable:true,sourceVersion:'fixture',observedAt:new Date(time).toISOString(),subjectDigest:subjectDigest(subject),binding:null}]);
 const executionStaging=createGitStagingHost({storageRoot:storage,gitExecutable});let executionRoot='',sawIsolatedMutation=false;
 const configuration:any={policy:{policyId:'policy',revision:1,digest:policy.digest},requirementIds:['fixture-requirement'],proposedPlan:{revision:'fixture-plan',policyRevision:'policy:1',policyDigest:policy.digest,tasks:[{id:'make',role:'implementation',ownerId:'fixture-maker',requirementIds:['fixture-requirement'],dependencyIds:[],candidateIds:['fixture-agent'],scopeIds:['work']},{id:'check',role:'verifier',ownerId:'fixture-checker',requirementIds:['fixture-requirement'],dependencyIds:['make'],candidateIds:['fixture-agent'],scopeIds:[]}]},scopes:[{id:'work',worktreeRealpath:publication,allowedActions:['file_change','read'],egress:[]}],budget:{runId:'workflow',currency:'TEST',unit:'micro',limitUnits:100,policyRevision:'policy:1',source:'fixture',observedAtMs:time},changeTargets:[{taskId:'make',targetId:'target',relativePath:'target.txt',maxBackupBytes:1024}],stagedPublication:true,executionStaging:true,limits:{launchTimeoutMs:10000,taskTimeoutMs:30000,pollMs:2}};
 const host:any={now:()=>time,catalog,prepare:()=>configuration,verifyFinalBilling:()=>true,executionStaging,
  finalPublication:{authorize:()=>true,openStagedAttempt:async(contract:any)=>{expect(contract).toMatchObject({version:'cue-staged-existing-files-v1',stagingOnly:true,worktreeRealpath:publication,targets:[{relativePath:'target.txt',maxBytes:1024}]});return{contractId:contract.contractId};},readStagedReplacement:async(input:any)=>{const row=db.prepare('SELECT execution_worktree_realpath FROM attempt_staging_authority WHERE attempt_id=?').get(input.attemptId) as any;executionRoot=row.execution_worktree_realpath;expect(executionRoot).not.toBe(publication);expect(readFileSync(join(publication,'target.txt'),'utf8')).toBe('base\n');expect(readFileSync(join(executionRoot,'target.txt'),'utf8')).toBe('replacement\n');sawIsolatedMutation=true;const bytes=readFileSync(join(executionRoot,'target.txt'));if(executionAfterRead==='restore')writeFileSync(join(executionRoot,'target.txt'),'base\n');if(executionAfterRead==='diverge')writeFileSync(join(executionRoot,'target.txt'),'diverged-after-read\n');return bytes;},execute:(input:any)=>compareWriteExistingNative(input)},
  authority:{authorizePlan:()=>true,authorizeClaim:()=>true,authorizeStage:()=>true,verifyReceipt:(context:any,receipt:any)=>{const identity=db.prepare('SELECT identity_id FROM orchestration_attempt_identity WHERE attempt_id=?').get(context.attemptId) as any;return{outcomeVerified:true,cleanupVerified:true,handoff:{handoffId:`fixture-handoff-${receipt.attemptId}`,identityId:identity.identity_id,artifacts:[{kind:'fixture',sourceRef:'fixture-artifact'}]}};},authorizeHandoffArtifact:(ref:string)=>ref==='fixture-artifact',resolveHandoffArtifact:(ref:string)=>ref==='fixture-artifact'?Buffer.from('fixture artifact'):null},
  runtime:{evidence:{now:()=>time,maxAgeMs:100,resolveEvidence:(ref:any)=>evidence.get(ref.id)},authorizeRun:()=>true,resolveCandidate:(_id:string,_attempt:string,_role:string,binding:any)=>({kind:'agent',supportedRoles:['implementation','model'],cancellation:'supported',usage:'unsupported',availability:'ready',typedActivitySource:'host-codex-controller-v1',durableExecutionRef:'session-handle-v1',stagedPublication:'attempt-owned-existing-files-v1',buildCurrentSubject:()=>subject,evidenceReferences:()=>refs,launch:async(context:any)=>{if(context.stagedPublication){executionRoot=binding.owner.cwd;expect(executionRoot).not.toBe(publication);expect(context.stagedPublication.stagingOnly).toBe(true);writeFileSync(join(executionRoot,'target.txt'),'replacement\n');expect(readFileSync(join(publication,'target.txt'),'utf8')).toBe('base\n');}const handle=`fixture-${sha(context.runId).slice(0,20)}`;db.prepare('INSERT INTO session_handle VALUES(?,?,?,?,?,?)').run(handle,101,'fixture-start',binding.owner.cwd,binding.owner.task_id,binding.owner.run_id);return{durableRef:`session:${handle}`,completion:Promise.resolve('succeeded'),cancel:async()=>{}};}}),verifyCleanup:async(context:any)=>({runId:context.runId,subjectDigest:context.subjectDigest,result:'verified-clean',evidenceRef:'fixture-clean'})},
  engine:{observeInitialSelection:()=>null,observeCandidates:()=>[{id:'fixture-agent',checks:{eligible:true,authenticated:true,compatible:true,dataAllowed:true,resourceAvailable:true,quotaAvailable:true},estimate:{scope:'verified-completion-total',quality:1,expectedCost:1,conservativeMaxCost:1,expectedTimeMs:1,conservativeMaxTimeMs:1,currency:'TEST',source:'fixture',observedAtMs:time}}],reservation:(context:any)=>({runId:context.request.runId,attemptId:context.request.attemptId,requestId:context.request.requestId,currency:'TEST',unit:'micro',upperUnits:1,source:'fixture',observedAtMs:time,scope:'verified-completion-attempt-total'}),verifyBudgetMapping:()=>true,authorizeExecution:()=>true,receipts:(context:any)=>({billing:null,execution:{runId:context.request.runId,taskId:context.request.taskId,attemptId:context.request.attemptId,receiptId:`fixture-receipt-${context.request.attemptId}`,revision:1,outcome:'succeeded',cleanup:'clean',evidenceRef:'fixture-clean',observedAtMs:time}})},stage:(context:any)=>({worktreeRealpath:join(storage,sha(context.request.attemptId),'worktree'),allowedActions:['file_change'],egress:[],expiresAt:envelope.expires_at,autonomyLevel:'bounded'})};
 configureHost?.({host,configuration,db,publication,storage,git:(...args:string[])=>git(publication,...args)});
 const driver=createOrchestrationDriver({db,host});const prepared=driver.prepare(run);db.prepare("INSERT INTO approval_event(run_id,envelope_hash,thread_id,item_id,approval_id,request_ordinal,decision,created_at) VALUES('workflow',?,'fixture-thread','fixture-goal','fixture-approval',0,'accept','now')").run(run.envelopeHash);const activated=driver.activate(run);
 return{db,driver,run,publication,storage,prepared,activated,host,get executionRoot(){return executionRoot;},get sawIsolatedMutation(){return sawIsolatedMutation;}};
}

